async function api(path,opts={}){const res=await fetch('/api'+path,{...opts,headers:opts.body instanceof FormData?{}:{'Content-Type':'application/json',...opts.headers},body:opts.body instanceof FormData?opts.body:opts.body?JSON.stringify(opts.body):undefined});let data;try{data=await res.json()}catch{throw new Error('Сессия закончилась или сервер недоступен. Обновите страницу.')}if(!res.ok)throw Object.assign(new Error(data.error||'Ошибка соединения'),{status:res.status});return data}
