function Modal({title,subtitle,children,onClose,wide=false}){const ref=useRef();useEffect(()=>{const old=document.activeElement;ref.current?.showModal();return()=>{old?.focus?.()}},[]);return <dialog ref={ref} className={'modal '+(wide?'wide':'')} onCancel={e=>{e.preventDefault();onClose()}} onClick={e=>{if(e.target===ref.current)onClose()}}><div className="modal-head"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><IconBtn label="Закрыть" onClick={onClose}><X size={20}/></IconBtn></div>{children}</dialog>}
function Field({label,children,wide=false,hint}){return <label className={'field '+(wide?'span2':'')}><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
