function CarForm({car,cars=[],onSave,onClose}){const[v,set]=useState(car?{...car,costBasis:{...car.costBasis}}:blank());const[customOwner,setCustomOwner]=useState(!!car?.owner&&!['Женя','Паша'].includes(car.owner));const[error,setError]=useState('');const[busy,setBusy]=useState(false);const change=(k,val)=>set(p=>{let n={...p,[k]:val};if(k==='country'){n.customsCountry=val==='Бишкек'?'Киргизия':(['Киргизия','Россия'].includes(p.customsCountry)?p.customsCountry:'Киргизия');if(!car){n.costBasis={...p.costBasis,purchaseCurrency:defaultCurrency(val)};}}if(k==='status'&&val!=='Продан')n.soldDate='';if(k==='brand'&&val.trim().toLowerCase()!==p.brand.trim().toLowerCase())n.model='';return n});const basis=v.costBasis||{};const purchase=purchaseInfo(v);const purchaseCurrency=purchase.currency;const setBasis=(k,val)=>set(p=>({...p,costBasis:{...p.costBasis,[k]:val}}));const setPurchase=(amount,currency)=>set(p=>{const old=purchaseInfo(p);const meta={...p.costBasis?.expenses?.[old.key]};if(currency!==old.currency){delete meta.perUsd;delete meta.krwPerUsd;}return {...p,costBasis:{...p.costBasis,krw:null,purchaseAmount:amount,purchaseCurrency:currency,expenses:{...p.costBasis?.expenses,purchaseAmount:meta}}}});const input=(k,props={})=><input value={v[k]??''} onChange={e=>change(k,k==='vin'?e.target.value.toUpperCase():e.target.value)} {...props}/>;async function submit(e){e.preventDefault();const errors=validateCar(v);if(errors.length){setError(errors.join('. '));return}setBusy(true);setError('');try{await onSave(v)}catch(e){setError(e.message)}finally{setBusy(false)}}return <Modal title={car?'Редактировать автомобиль':'Новый автомобиль'} subtitle="Обязательны только марка и модель. Остальное можно добавить позже." onClose={()=>!busy&&onClose()} wide><form onSubmit={submit}><div className="modal-body"><div className="form-grid"><VehiclePicker label="Марка" value={v.brand} onChange={x=>change('brand',x)} groups={brandGroups(cars)}/><VehiclePicker label="Модель" value={v.model} onChange={x=>change('model',x)} groups={modelGroups(v.brand,cars)} disabled={!v.brand.trim()}/><Field label="VIN" wide hint="17 символов. Буквы I, O и Q не используются.">{input('vin',{placeholder:'Введите VIN автомобиля',maxLength:17,minLength:17,className:'mono'})}</Field><Field label="Год выпуска">{input('year',{type:'number',min:1950,max:new Date().getFullYear()+2})}</Field>{car&&<Field label="Месяц выпуска">{input('productionMonth',{type:'month'})}</Field>}<Field label="Собственник"><select value={customOwner?'__new':v.owner||''} onChange={e=>{setCustomOwner(e.target.value==='__new');change('owner',e.target.value==='__new'?'':e.target.value)}}><option value="">Не указан</option><option>Женя</option><option>Паша</option><option value="__new">Новый собственник</option></select>{customOwner&&input('owner',{placeholder:'Имя нового собственника'})}</Field><Field label="Комплектация">{input('trim',{placeholder:'AMG Line · 3.0 дизель'})}</Field><Field label="Цвет">{input('color',{list:'vehicle-colors',placeholder:'Выберите или введите цвет'})}<datalist id="vehicle-colors">{['Белый','Чёрный','Серый','Серебристый','Синий','Красный','Зелёный','Коричневый','Бежевый','Жёлтый','Оранжевый','Фиолетовый','Золотой'].map(x=><option key={x} value={x}/>)}</datalist></Field><Field label="Пробег, км">{input('mileage',{type:'number',min:0,step:1})}</Field><div className="form-separator span2">Покупка автомобиля</div><Field label="Статус"><select value={v.status} onChange={e=>change('status',e.target.value)}>{!STATUSES.includes(v.status)&&<option value={v.status} disabled>{v.status} (прежний статус)</option>}{(car?STATUSES:['Забронирован','Выкуплен']).map(s=><option key={s} value={s}>{s==='Забронирован'?'Бронь':s==='Выкуплен'?'Оплата':s}</option>)}</select></Field><Field label="Страна вывоза"><select value={v.country||''} onChange={e=>change('country',e.target.value)}><option value="">Не указана</option>{v.country&&!EXPORT_ORIGINS.includes(v.country)&&<option value={v.country}>{v.country} (ранее указано)</option>}{EXPORT_ORIGINS.map(x=><option key={x}>{x}</option>)}</select></Field>{v.country&&<Field label="Таможня"><select value={v.customsCountry||(v.country==='Бишкек'?'Киргизия':'')} onChange={e=>change('customsCountry',e.target.value)}><option value="">Не указана</option><option>Киргизия</option>{v.country!=='Бишкек'&&<option>Россия</option>}</select></Field>}<Field label="Стоимость автомобиля"><input type="number" min="0" step="any" value={purchase.amount??''} onChange={e=>setPurchase(e.target.value,purchaseCurrency)}/></Field><Field label="Валюта стоимости"><select value={purchaseCurrency} onChange={e=>setPurchase(purchase.amount??null,e.target.value)}>{PURCHASE_CURRENCIES.map(c=><option key={c} value={c}>{c} · {currencySymbol(c)}</option>)}</select></Field>{!['USD','RUB'].includes(purchaseCurrency)&&<Field label={'Курс: '+currencySymbol(purchaseCurrency)+' за $1'}><input type="number" min="0.0001" step="any" value={basis[rateField(purchaseCurrency)]??''} onChange={e=>setBasis(rateField(purchaseCurrency),e.target.value)}/></Field>}<Field label="Курс доллара: ₽ за $1"><input type="number" min="0.0001" step="any" value={basis.usdRub??''} onChange={e=>setBasis('usdRub',e.target.value)}/></Field><Field label="Дата покупки">{input('purchaseDate',{type:'date',max:today()})}</Field>{v.status==='Продан'?<Field label="Дата продажи">{input('soldDate',{type:'date',max:today()})}</Field>:<div/>}<div className="form-separator span2">Продажа и заметки</div><Field label="Цена продажи, ₽" hint="Себестоимость формируется отдельно из расходов.">{input('price',{type:'number',min:0,step:1})}</Field><Field label="Контакт / примечание">{input('contact',{placeholder:'Имя, телефон или заметка'})}</Field><Field label="Заметки" wide><textarea rows="3" value={v.notes} maxLength="5000" onChange={e=>change('notes',e.target.value)} placeholder="Что важно знать об этом автомобиле"/></Field></div>{error&&<div className="error" role="alert"><AlertCircle size={17}/>{error}</div>}</div><div className="modal-foot"><button type="button" className="btn" disabled={busy} onClick={onClose}>Отмена</button><button className="btn primary" disabled={busy}>{busy?<Loader2 size={17} className="spin"/>:<Check size={17}/>} {car?'Сохранить изменения':'Добавить автомобиль'}</button></div></form></Modal>}
function SmallForm({kind,car,item,category,onSave,onClose}){const initial=kind==='cost'?item||{type:'Покупка',description:'',amount:'',currency:'RUB',rate:1,paid:false,date:today()}:kind==='route'?item||{stage:'purchased',date:today()}:{category:category||'Документ'};const[v,set]=useState(initial);const[error,err]=useState('');const[busy,bus]=useState(false);const[file,sf]=useState(null);const upd=(k,val)=>set(p=>({...p,[k]:val}));async function submit(e){e.preventDefault();bus(true);err('');try{await onSave(kind,v,file,item)}catch(e){err(e.message)}finally{bus(false)}}return <Modal title={kind==='cost'?(item?'Изменить расход':'Добавить расход'):kind==='route'?(item?'Изменить этап маршрута':'Новый этап маршрута'):category==='Фото'?'Добавить фото':'Загрузить документ'} subtitle={car.brand+' '+car.model} onClose={()=>!busy&&onClose()}><form onSubmit={submit}><div className="modal-body"><div className="form-grid">{kind==='cost'?<><Field label="Статья расхода" wide><select value={v.type} onChange={e=>upd('type',e.target.value)}>{COST_TYPES.map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Сумма *"><input autoFocus type="number" min="0.01" step="0.01" required value={v.amount} onChange={e=>upd('amount',e.target.value)}/></Field><Field label="Валюта"><select value={v.currency} onChange={e=>{upd('currency',e.target.value);upd('rate',e.target.value==='RUB'?1:'')}}>{['RUB','USD','EUR','CNY','AED'].map(x=><option key={x}>{x}</option>)}</select></Field>{v.currency!=='RUB'&&<Field label={'Курс: ₽ за 1 '+v.currency} wide hint={v.currency==='USD'?'Оставьте пустым, чтобы использовать общий курс автомобиля: '+(car.costBasis?.usdRub||'не указан'):'Укажите фактический курс покупки.'}><input type="number" min="0.0001" step="0.0001" required={v.currency!=='USD'} placeholder={v.currency==='USD'?String(car.costBasis?.usdRub||''):''} value={v.rate??''} onChange={e=>upd('rate',e.target.value)}/></Field>}<Field label="Дата *" wide><input type="date" required value={v.date} onChange={e=>upd('date',e.target.value)}/></Field><Field label="Описание" wide><input value={v.description} onChange={e=>upd('description',e.target.value)} placeholder="Например, доставка из Дубая"/></Field><label className="expense-paid-field span2"><input type="checkbox" checked={v.paid===true} onChange={e=>upd('paid',e.target.checked)}/> Расход оплачен</label><div className="cost-preview span2"><span>В себестоимость</span><strong>{expenseRate(car,v)?money(Number(v.amount)*expenseRate(car,v)):'Нужен курс'}</strong></div></>:kind==='route'?<><Field label="Этап"><select required value={v.stage} onChange={e=>upd('stage',e.target.value)}>{ROUTE_STAGES.map(x=><option key={x.id} value={x.id}>{x.label}</option>)}</select></Field><Field label="Дата"><input type="date" required max={today()} value={v.date} onChange={e=>upd('date',e.target.value)}/></Field></>:<><Field label="Категория" wide><select value={v.category} onChange={e=>upd('category',e.target.value)}>{(category==='Фото'?['Фото']:FILE_TYPES.filter(x=>!['Фото','Видео'].includes(x))).map(x=><option key={x}>{x}</option>)}</select></Field><label className="upload-zone span2"><Upload size={26}/><strong>{file?file.name:'Выберите файл'}</strong><span>{category==='Фото'?'JPG, PNG, WEBP · до 10 МБ':'PDF, Word, Excel, сканы, TXT, CSV · до 10 МБ'}</span><input type="file" required accept={v.category==='Фото'?'.jpg,.jpeg,.png,.webp':'.jpg,.jpeg,.png,.webp,.pdf,.doc,.docx,.xls,.xlsx,.txt,.csv'} onChange={e=>sf(e.target.files?.[0]||null)}/></label><p className="form-note span2">Файл сохранится в облаке и будет доступен из этой карточки.</p></>}</div>{error&&<div className="error" role="alert">{error}</div>}</div><div className="modal-foot"><button type="button" className="btn" onClick={onClose} disabled={busy}>Отмена</button><button className="btn primary" disabled={busy}>{busy?<Loader2 size={17} className="spin"/>:<Plus size={17}/>} {kind==='upload'?'Загрузить':'Сохранить'}</button></div></form></Modal>}
function PartyForm({role,party,recognized,onSave,onClose}){
 const [values,setValues]=useState(()=>mergePassportFields(Object.fromEntries(PARTY_FIELDS.map(([key])=>[key,party?.[key]||''])),recognized?.fields||{}).values);
 const [conflicts,setConflicts]=useState(()=>mergePassportFields(party||{},recognized?.fields||{}).conflicts);
 const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [ocrBusy,setOcrBusy]=useState(false);const [passportFiles,setPassportFiles]=useState([]);const [detected,setDetected]=useState(Object.keys(recognized?.fields||{}));const label=role==='buyer'?'покупателя':'продавца';
 async function submit(e){e.preventDefault();const next=Object.fromEntries(Object.entries(values).map(([key,value])=>[key,value.trim()]));const errors=validateParty(next);if(errors.length){setError(errors.join('. '));return;}setBusy(true);setError('');try{await onSave(role,next,passportFiles)}catch(e){setError(e.message)}finally{setBusy(false)}}
 return <Modal title={(party?'Редактировать':'Добавить')+' '+label} subtitle="ФИО обязательно. Остальные данные можно заполнить позже." onClose={()=>!busy&&!ocrBusy&&onClose()} wide><form onSubmit={submit}><div className="modal-body">{recognized&&<p className="fine-print">Распознавание завершено. Проверьте данные и нажмите «Сохранить».</p>}{recognized?.warnings?.map(w=><p className="fine-print" key={w}>{w}</p>)}{!!Object.keys(conflicts).length&&<div className="ocr-conflicts"><b>Данные отличаются от заполненных</b>{Object.entries(conflicts).map(([key,value])=><div key={key}><span>{PARTY_FIELDS.find(f=>f[0]===key)?.[1]}: {value}</span><button type="button" className="text-btn" onClick={()=>{setValues(v=>({...v,[key]:value}));setConflicts(c=>{const n={...c};delete n[key];return n})}}>Использовать из паспорта</button></div>)}</div>}<fieldset className="party-fields" disabled={busy||ocrBusy}><div className="form-grid">{PARTY_FIELDS.map(([key,label,max,type])=><Field key={key} hint={detected.includes(key)?'Распознано — сверьте с паспортом':undefined} label={label+(key==='fullName'?' *':'')} wide={['fullName','passportIssuedBy','address'].includes(key)}>{['address','passportIssuedBy'].includes(key)?<textarea className={detected.includes(key)?'ocr-field':undefined} rows="2" maxLength={max} value={values[key]} onChange={e=>setValues(v=>({...v,[key]:e.target.value}))}/>:<input className={detected.includes(key)?'ocr-field':undefined} autoFocus={key==='fullName'} required={key==='fullName'} type={type||'text'} max={type==='date'?today():undefined} maxLength={max} value={values[key]} onChange={e=>setValues(v=>({...v,[key]:e.target.value}))}/>}</Field>)}</div></fieldset>{error&&<div className="error" role="alert">{error}</div>}</div><div className="modal-foot"><button className="btn" type="button" disabled={busy||ocrBusy} onClick={onClose}>Отмена</button><button className="btn primary" disabled={busy||ocrBusy}>{busy?<Loader2 size={17} className="spin"/>:<Check size={17}/>} Сохранить</button></div></form></Modal>
}
function SalePrice({car,onSaved,readOnly}){
 const [editing,setEditing]=useState(false),[value,setValue]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[snapshot,setSnapshot]=useState(null);
 async function save(e){e.preventDefault();setBusy(true);setError('');try{const updated=await api('/cars/'+car.id,{method:'PATCH',body:{...snapshot,price:value===''?0:Number(value)}});onSaved(updated);setEditing(false)}catch(e){setError(e.message)}finally{setBusy(false)}}
 return <div className="sale-price-control" onClick={e=>e.stopPropagation()}>{readOnly?<strong className="inventory-money accent-text">{car.price?money(car.price):'Не задана'}</strong>:<button type="button" className="sale-price-button inventory-money accent-text" title="Изменить цену продажи" onClick={()=>{setSnapshot({...car});setValue(car.price||'');setError('');setEditing(true)}}>{car.price?money(car.price):'Не задана'}<Pencil size={15}/></button>}{editing&&<Modal title="Цена продажи" subtitle={car.brand+' '+car.model} onClose={()=>!busy&&setEditing(false)}><form onSubmit={save}><div className="modal-body"><Field label="Цена продажи, ₽"><input autoFocus type="number" min="0" step="0.01" value={value} disabled={busy} onChange={e=>setValue(e.target.value)}/></Field>{error&&<div className="error" role="alert">{error}</div>}</div><div className="modal-foot"><button type="button" className="btn" disabled={busy} onClick={()=>setEditing(false)}>Отмена</button><button className="btn primary" disabled={busy}>{busy?<Loader2 size={17} className="spin"/>:<Check size={17}/>} Сохранить</button></div></form></Modal>}</div>
}
function WebsiteToggle({car,api,onSaved,canEdit}){const [busy,setBusy]=useState(false),[error,setError]=useState('');const blocked=car.isDemo||car.archived||car.status==='Продан'||!!car.soldDate;return <div className="website-toggle" onClick={e=>e.stopPropagation()}><label><input type="checkbox" aria-label={'Выгрузить на сайт '+car.brand+' '+car.model} checked={!!car.publication?.enabled&&!blocked} disabled={!canEdit||busy||blocked} onChange={async e=>{const enabled=e.target.checked;setBusy(true);setError('');try{onSaved(await api('/cars/'+car.id+'/publication',{method:'PATCH',body:{revision:car.revision,enabled,description:car.publication?.description||'',photoIds:[],autoPhotos:true}}))}catch(e){setError(e.message)}finally{setBusy(false)}}}/> {busy?'Сохраняю…':'На сайт'}</label>{error&&<small role="alert">{error}</small>}</div>}
function PartyCard({role,party,car,onUpload,onRecognized,onDelete,onEdit,readOnly}){
 const label=role==='buyer'?'Покупатель':'Продавец';const [busy,setBusy]=useState(''),[error,setError]=useState('');const input=useRef();
 const files=(car.files||[]).filter(f=>f.partyRole===role);const [pending,setPending]=useState(null);const [viewing,setViewing]=useState(null);
 function upload(e){const picked=Array.from(e.target.files||[]);e.target.value='';if(!picked.length)return;setError('');try{checkPassportFiles(picked);setPending({files:picked,saved:false})}catch(e){setError(e.message)}}
 async function process(recognize){setBusy(recognize?'recognize':'upload');setError('');let saved=pending.saved;try{if(!saved){await onUpload(pending.files);saved=true;setPending(p=>({...p,saved:true}))}if(recognize){const result=await recognizePassport(pending.files.map(file=>({file,rotation:0})));if(!Object.keys(result.fields||{}).length)throw new Error(result.warnings?.join(' ')||'Данные не распознаны. Попробуйте более чёткие фото.');setPending(null);onRecognized(result)}else setPending(null)}catch(e){setError((saved?'Файлы сохранены в документах. ':'')+e.message)}finally{setBusy('')}}
 return <article className={'party-card '+(party?'filled':'')}><div className="party-heading"><div><span className="party-role">{label}</span><h3>{party?.fullName||'Не добавлен'}</h3></div>{!readOnly&&<IconBtn label={(party?'Редактировать':'Добавить')+' '+(role==='buyer'?'покупателя':'продавца')} disabled={!!busy} onClick={onEdit}>{party?<Pencil size={18}/>:<Plus size={21}/>}</IconBtn>}</div>
 {party&&<dl className="party-summary">{PARTY_FIELDS.filter(([k])=>k!=='fullName'&&party[k]).map(([k,label,max,type])=><div key={k}><dt>{label}</dt><dd>{type==='date'?date(party[k]):party[k]}</dd></div>)}</dl>}
 {files.length>0&&<div className="party-documents">{files.map(f=><div key={f.id} className="passport-saved-file"><button type="button" className="party-document-open" onClick={()=>setViewing(f)}><FileText size={18}/><span>{f.name}</span></button><a className="icon-btn party-download" href={'/api/cars/'+car.id+'/files/'+f.id+'?download=1'} download={f.name} title="Скачать" aria-label={'Скачать '+f.name}><Download size={17}/></a>{!readOnly&&<IconBtn label={'Удалить '+f.name} disabled={!!busy} onClick={()=>onDelete(f)}><Trash2 size={16}/></IconBtn>}</div>)}</div>}
 {!readOnly&&<div className="passport-actions party-upload"><input ref={input} hidden type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf" onChange={upload} disabled={!!busy}/><button type="button" className="btn" disabled={!!busy} onClick={()=>input.current.click()}><Upload size={16}/> Загрузить файл</button></div>}
 {error&&!pending&&<div className="error" role="alert">{error}</div>}
 {viewing&&<DocumentPreview car={car} file={viewing} onClose={()=>setViewing(null)}/>}
 {pending&&<Modal title={'Паспорт '+(role==='buyer'?'покупателя':'продавца')} subtitle="Выберите действие для файлов" onClose={()=>{if(!busy){setPending(null);setError('')}}}><div className="modal-body"><ul className="upload-queue">{pending.files.map((f,i)=><li key={i}>{f.name}</li>)}</ul><p className="fine-print">«Загрузить» сохранит документы без заполнения формы. «Загрузить и распознать» также прочитает паспорт через AI и откроет данные для проверки.</p>{pending.saved&&<p>Файлы уже сохранены. Повторное распознавание не создаст копии.</p>}{error&&<div className="error" role="alert">{error}</div>}</div><div className="modal-foot"><button type="button" className="btn" disabled={!!busy} onClick={()=>process(false)}>{pending.saved?'Готово':'Загрузить'}</button><button type="button" className="btn primary" disabled={!!busy} onClick={()=>process(true)}>{busy?<><Loader2 size={16} className="spin"/> Обработка…</>:pending.saved?'Распознать':'Загрузить и распознать'}</button></div></Modal>}</article>

}
function ContractForm({car,onSave,onClose}){
 const purchase=car.costs.find(x=>x.type==='Покупка');const usd=purchase?.currency==='USD'?purchase.amount:'';const rub=purchase?Math.round(purchase.amount*purchase.rate*100)/100:'';
 const[v,set]=useState({contractNo:`DKP-${new Date().getFullYear()}-${(car.vin||car.id).slice(-4)}`,contractDate:today(),priceUsd:usd,priceRub:rub,invoiceNo:'',invoiceDate:today(),...car.contractDraft,...(car.payment?.contractAmountRub!=null?{priceRub:car.payment.contractAmountRub}:{})});const[error,err]=useState('');const[busy,bus]=useState(false);const upd=(k,value)=>set(x=>({...x,[k]:value}));
 async function submit(e){e.preventDefault();bus(true);err('');try{await onSave(v)}catch(e){err(e.message)}finally{bus(false)}}
 return <Modal title="Сгенерировать договор" subtitle={`${car.brand} ${car.model} · данные сторон подставятся автоматически`} onClose={()=>!busy&&onClose()} wide><form onSubmit={submit}><div className="modal-body"><div className="contract-parties"><div><span>ПРОДАВЕЦ</span><b>{car.seller?.fullName}</b></div><ArrowUpRight size={17}/><div><span>ПОКУПАТЕЛЬ</span><b>{car.buyer?.fullName}</b></div></div><div className="form-grid"><Field label="Номер договора *"><input required maxLength="100" value={v.contractNo} onChange={e=>upd('contractNo',e.target.value)}/></Field><Field label="Дата договора *"><input required type="date" max={today()} value={v.contractDate} onChange={e=>upd('contractDate',e.target.value)}/></Field><Field label="Стоимость авто, USD *"><input required autoFocus type="number" min="0.01" step="0.01" value={v.priceUsd} onChange={e=>upd('priceUsd',e.target.value)}/></Field><Field label="Стоимость авто, RUB *"><input required type="number" min="0.01" step="0.01" value={v.priceRub} onChange={e=>upd('priceRub',e.target.value)}/></Field><Field label="Номер инвойса *"><input required maxLength="100" value={v.invoiceNo} onChange={e=>upd('invoiceNo',e.target.value)} placeholder="Например, INV-2026-001"/></Field><Field label="Дата инвойса *"><input required type="date" max={today()} value={v.invoiceDate} onChange={e=>upd('invoiceDate',e.target.value)}/></Field></div><p className="form-note contract-note">Будет создан редактируемый Word-файл и автоматически сохранён в документах автомобиля.</p>{error&&<div className="error" role="alert"><AlertCircle size={17}/>{error}</div>}</div><div className="modal-foot"><button type="button" className="btn" onClick={onClose} disabled={busy}>Отмена</button><button className="btn primary" disabled={busy}>{busy?<Loader2 size={17} className="spin"/>:<FileText size={17}/>} Создать и скачать</button></div></form></Modal>
}
function CarFiles({car,photos,onUpload,onVideo,onGenerate,onPreview,onDelete,onCover,onMove}){
 const items=car.files.filter(f=>photos?f.category==='Фото':!['Фото','Видео'].includes(f.category));const title=photos?'Фото':'Документы';
 return <section className="panel"><div className="panel-title"><div><h2>{title} <span>{items.length}</span></h2><p>{photos?'Фотографии автомобиля · первое фото — обложка':'Инвойсы, договоры, чеки и другие документы автомобиля'}</p></div><div className="media-buttons">{photos&&<button className="btn" data-write="" disabled={!items.length} onClick={onGenerate}>Сгенерировать фото</button>}{photos&&<button className="btn" data-write="" onClick={onVideo}>＋ Добавить видео</button>}<button className="btn primary" data-write="" onClick={onUpload}><Upload size={16}/> {photos?'Добавить фото':'Загрузить документ'}</button></div></div>{!items.length?<div className="empty dashed">{photos?<ImageIcon size={30}/>:<FileText size={30}/>}<h3>{photos?'Добавьте фотографии':'Добавьте документы'}</h3><p>{photos?'JPG, PNG или WEBP · до 10 МБ на фото':'PDF, Word, Excel и сканы документов · до 10 МБ'}</p><button className="btn" data-write="" onClick={onUpload}>Выбрать файл</button></div>:photos?<div className="photo-grid photo-gallery">{items.map((f,index)=><article className="photo-card" key={f.id}><button className="photo-preview" onClick={()=>onPreview(f)} aria-label={'Открыть '+f.name}><img loading="lazy" src={'/api/cars/'+car.id+'/files/'+f.id} alt={f.name}/></button><div className="photo-caption"><div><b title={f.name}>{f.name}</b><small>{size(f.size)}</small><div className="photo-order-actions" data-write=""><button type="button" className="icon-btn" aria-label="Переместить фото назад" disabled={index===0} onClick={()=>onMove(f,-1)}>←</button><span>{index+1} / {items.length}</span><button type="button" className="icon-btn" aria-label="Переместить фото вперёд" disabled={index===items.length-1} onClick={()=>onMove(f,1)}>→</button></div><button type="button" className="photo-cover-btn" data-write="" disabled={items[0]?.id===f.id} onClick={()=>onCover(f)}>{items[0]?.id===f.id?'✓ Обложка':'Сделать обложкой'}</button></div><a className="icon-btn" aria-label={'Скачать '+f.name} href={'/api/cars/'+car.id+'/files/'+f.id} download={f.name}><Download size={16}/></a><IconBtn label={'Удалить '+f.name} onClick={()=>onDelete(f)}><Trash2 size={16}/></IconBtn></div></article>)}</div>:<div className="file-list">{items.map(f=><div className="file-row" key={f.id}><span className="file-icon">{f.category==='Чек'?<Receipt/>:<FileText/>}</span><div className="file-name"><DocumentLink car={car} file={f}/><span>{f.category} · {size(f.size)} · {date(f.date)}</span></div><IconBtn label={'Удалить '+f.name} onClick={()=>onDelete(f)}><Trash2 size={16}/></IconBtn></div>)}</div>}</section>
}
function App({session}){const readOnly=session.role==='viewer',isOwner=session.role==='owner';const[cars,setCars]=useState([]);const[loading,load]=useState(true);const[error,err]=useState('');const[nav,setNav]=useState(location.hash.startsWith('#intake')?'intake':location.hash.startsWith('#encar')?'encar':'cars');const[query,setQuery]=useState('');const[status,ss]=useState('Все');const[country,sc]=useState('Все страны');const[sort,so]=useState('new');const[view,sv]=useState('list');const[archive,sa]=useState(false);const[selected,select]=useState(readCarHash(location.hash).id);const[tab,st]=useState(readCarHash(location.hash).tab);const[modal,setModal]=useState(null);const sm=m=>{if(m&&readOnly&&m.kind!=='help')return;if(m&&!isOwner&&(m.action==='archive'||m.action==='demo'||m.action==='delete-car'))return;setModal(m)};const[toast,tt]=useState('');const[menu,showMenu]=useState(false);const[photo,sp]=useState(null);const[busy,sb]=useState(false);const[fileFilter,sff]=useState('Все');
 async function refresh(){load(true);err('');try{const d=await api('/cars');setCars(d.cars)}catch(e){err(e.message)}finally{load(false)}}useEffect(()=>{refresh();const fn=()=>{if(location.hash.startsWith('#intake'))setNav('intake');else if(location.hash.startsWith('#encar'))setNav('encar');const target=readCarHash(location.hash);select(target.id);st(target.tab)};window.addEventListener('hashchange',fn);return()=>window.removeEventListener('hashchange',fn)},[]);useEffect(()=>{if(toast){const t=setTimeout(()=>tt(''),4500);return()=>clearTimeout(t)}},[toast]);
 const current=cars.find(c=>c.id===selected);const active=cars.filter(c=>!c.archived);const filtered=useMemo(()=>cars.filter(c=>c.archived===archive&&(status==='Все'||c.status===status)&&(country==='Все страны'||(country==='Не указана'?!c.country:c.country===country))&&[c.brand,c.model,c.owner,c.vin,c.location,c.contact,c.buyer?.fullName,c.seller?.fullName].join(' ').toLowerCase().includes(query.trim().toLowerCase())).sort((a,b)=>sort==='country'?compareExportOrigin(a,b):sort==='cost'?costTotal(b)-costTotal(a):sort==='days'?(daysInStock(b)||0)-(daysInStock(a)||0):sort==='name'?(a.brand+a.model).localeCompare(b.brand+b.model):b.createdAt.localeCompare(a.createdAt)),[cars,archive,status,country,query,sort]);
 const open=(c,section='overview')=>{location.hash=carHash(c.id,section);select(c.id);st(section);showMenu(false)};const back=()=>{history.pushState(null,'',location.pathname);select(null)};const go=n=>{back();setNav(n);if(n==='encar'||n==='intake')history.replaceState(null,'','#'+n);showMenu(false)};const upsert=c=>setCars(p=>p.some(x=>x.id===c.id)?p.map(x=>x.id===c.id?c:x):[c,...p]);
 async function saveCar(v){const c=await api(current&&modal?.kind==='edit'?'/cars/'+current.id:'/cars',{method:modal?.kind==='edit'?'PATCH':'POST',body:v});upsert(c);sm(null);open(c);tt('Карточка сохранена в облаке')}
 function deleteDocument(f){sm({kind:'confirm',action:'files',item:f,title:'Удалить документ?',text:f.name+' будет удалён из документов автомобиля.'})}
 async function uploadPassport(role,files){const fd=new FormData();fd.set('party','{}');fd.set('passportOnly','true');fd.set('revision',current.revision);for(const f of files)fd.append('passport',f);const c=await api('/cars/'+current.id+'/parties/'+role,{method:'PATCH',body:fd});upsert(c);tt('Паспорт сохранён в документах');return c}
 async function saveParty(role,party,files=[]){let body={party,revision:current.revision};if(files.length){body=new FormData();body.set('party',JSON.stringify(party));body.set('revision',current.revision);for(const file of files)body.append('passport',file)}const c=await api('/cars/'+current.id+'/parties/'+role,{method:'PATCH',body});upsert(c);sm(null);tt(role==='buyer'?'Покупатель сохранён':files.length?'Продавец и паспорт сохранены':'Продавец сохранён')}
 async function saveContract(values){const result=await api('/cars/'+current.id+'/contracts',{method:'POST',body:{...values,revision:current.revision}});upsert(result.car);sm(null);tt('Договор создан и сохранён в документах');const a=document.createElement('a');a.href='/api/cars/'+current.id+'/files/'+result.file.id;a.download=result.file.name;document.body.appendChild(a);a.click();a.remove()}
 async function saveSmall(kind,v,file,item){const path='/cars/'+current.id;let c;if(kind==='upload'){if(!file)throw new Error('Выберите файл');const fd=new FormData();fd.set('file',file);fd.set('category',v.category);fd.set('revision',current.revision);c=await api(path+'/files',{method:'POST',body:fd})}else c=await api(path+'/'+(kind==='cost'?'costs':'route')+(item?'/'+item.id:''),{method:item?'PATCH':'POST',body:{...v,revision:current.revision}});upsert(c);sm(null);tt(kind==='upload'?'Файл сохранён в облаке':'Изменения сохранены')}
 function exportData(){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),cars},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='vector-crm-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);tt('Выгружены карточки, расходы и история. Сами файлы скачиваются отдельно.')}
 function deleteCar(c){sm({kind:'confirm',action:'delete-car',item:c,title:'Удалить автомобиль?',text:c.brand+' '+c.model+(c.vin?' · VIN '+c.vin:'')+'. Карточка, фотографии, видео, документы, расходы и история будут удалены без возможности восстановления. Объявление также исчезнет с сайта.'})}
 async function confirmed(){sb(true);try{if(modal.action==='delete-car'){await api('/cars/'+modal.item.id,{method:'DELETE',body:{revision:modal.item.revision,confirm:'delete-car'}});setCars(p=>p.filter(c=>c.id!==modal.item.id));if(selected===modal.item.id)back();tt('Автомобиль удалён')}else if(modal.action==='demo'){await api('/demo',{method:'DELETE',body:{confirm:'delete-demo'}});setCars(p=>p.filter(c=>!c.isDemo));back();tt('Тестовые записи удалены')}else if(modal.action==='archive'){const c=await api('/cars/'+current.id+'/archive',{method:'POST',body:{revision:current.revision,archived:!current.archived}});upsert(c);back();tt(c.archived?'Автомобиль в архиве':'Автомобиль восстановлен')}else{const c=await api('/cars/'+current.id+'/'+modal.action+'/'+modal.item.id,{method:'DELETE',body:{revision:current.revision}});upsert(c);tt('Удалено. Действие записано в историю')}sm(null)}catch(e){tt(e.message)}finally{sb(false)}}
 const demoCount=cars.filter(c=>c.isDemo).length;const inventoryTotal=active.filter(c=>c.status!=='Продан').some(c=>costTotal(c)===null)?null:active.filter(c=>c.status!=='Продан').reduce((a,c)=>a+costTotal(c),0);const allFiles=active.flatMap(c=>c.files.map(f=>({...f,car:c}))).filter(f=>!['Фото','Видео'].includes(f.category)&&(fileFilter==='Все'||f.category===fileFilter)&&[f.name,f.car.brand,f.car.model,f.car.vin].join(' ').toLowerCase().includes(query.toLowerCase()));const allHistory=active.flatMap(c=>c.history.map(h=>({...h,car:c}))).sort((a,b)=>b.date.localeCompare(a.date));
 return <div className="app" data-role={session.role}><aside className={'sidebar '+(menu?'open':'')}><a className="brand" href="#" onClick={e=>{e.preventDefault();go('cars')}}><span className="brand-symbol">V<span/></span><div>VECTOR<span>AUTO MANAGEMENT</span></div></a><div className="workspace"><span className="workspace-icon"><CarFront size={19}/></span><div><b>Автомобильный бизнес</b><span>Личное пространство</span></div><ChevronDown size={14}/></div><span className="nav-caption">РАБОЧЕЕ ПРОСТРАНСТВО</span><nav>{[['cars',CarFront,'Автомобили',active.length],['files',Files,'Документы',active.reduce((a,c)=>a+c.files.filter(f=>!['Фото','Видео'].includes(f.category)).length,0)],['history',History,'История изменений'],['encar',Wallet,'Расчёт Encar'],...(isOwner?[['intake',Files,'Из групп Telegram'],['staff',ShieldCheck,'Доступы']]:[])].map(([id,I,label,count])=><button key={id} className={nav===id?'active':''} onClick={()=>go(id)}><I size={19}/><span>{label}</span>{count!==undefined&&<em>{count}</em>}</button>)}</nav><div className="sidebar-bottom"><a className="sidebar-site" href={BOOM_ORIGIN} target="_blank" rel="noreferrer"><ExternalLink size={19}/><span>Сайт</span><ArrowUpRight size={16}/></a><div className="private-note"><ShieldCheck size={19}/><div><b>Приватное пространство</b><span>Доступ по личным аккаунтам</span></div></div><button className="user-profile" onClick={()=>sm({kind:'help'})}><span className="avatar">ПЕ</span><div><b>{session.user.name}</b><span>{ROLE_LABELS[session.role]} · VECTOR</span></div><HelpCircle size={17}/></button></div></aside>{menu&&<div className="menu-overlay" onClick={()=>showMenu(false)}/>}
 <main><header className="topbar"><div className="breadcrumb"><IconBtn label="Меню" onClick={()=>showMenu(!menu)}><Menu size={20}/></IconBtn><span>Рабочее пространство</span><ChevronRight size={14}/><b>{current?'Карточка автомобиля':nav==='cars'?'Автомобили':nav==='files'?'Документы':nav==='intake'?'Из групп Telegram':nav==='staff'?'Доступы':nav==='encar'?'Расчёт Encar':'История изменений'}</b></div><div className="top-right"><span className="cloud-status"><i/>{loading?'Подключение…':error?'Нет соединения':'Облачное сохранение'}</span><IconBtn label="Обновить данные" onClick={refresh}><RotateCcw size={17}/></IconBtn><span className="avatar small">ПЕ</span></div></header>
 <div className="content"><div className="session-banner"><span>{session.user.name} · {ROLE_LABELS[session.role]}</span>{session.user.authMethod==='link'?<button className="text-btn" onClick={async()=>{await api('/login/logout',{method:'POST'});location.assign('/')}}>Выйти</button>:<a href="/signout-with-chatgpt?return_to=%2F" target="_top">Выйти</a>}</div>{nav==='staff'&&isOwner&&<StaffPanel api={api}/>}{nav==='intake'&&isOwner&&!current&&<TelegramIntake api={api} cars={cars} onSaved={upsert}/>}{error&&<div className="error"><AlertCircle size={18}/>{error}<button className="text-btn" onClick={refresh}>Повторить</button></div>}{loading&&!cars.length?<div className="loading"><Loader2 className="spin"/> Загружаем ваш склад…</div>:selected&&!current?<div className="empty"><CarFront size={38}/><h2>Карточка не найдена</h2><button className="btn" onClick={back}>Вернуться к автомобилям</button></div>:current?<>
 <button className="back-link" onClick={back}><ArrowLeft size={16}/> Все автомобили</button><div className="page-heading card-heading"><div><div className="eyebrow">КАРТОЧКА АВТОМОБИЛЯ {current.isDemo&&<span>ТЕСТОВЫЕ ДАННЫЕ</span>}</div><h1>{current.brand} <span>{current.model}</span></h1><p>{current.year||'Год не указан'} <i>·</i> {current.trim||'Комплектация не указана'} <i>·</i> {current.color||'Цвет не указан'}</p></div><div className="heading-actions">{isOwner&&<button className="btn danger" onClick={()=>deleteCar(current)}><Trash2 size={17}/> Удалить</button>}<button className="btn" data-write="" data-owner="" onClick={()=>sm({kind:'confirm',action:'archive',title:current.archived?'Восстановить автомобиль?':'Переместить в архив?',text:current.archived?'Карточка вернётся в основной список.':'Карточка, расходы и документы сохранятся. Автомобиль можно восстановить из архива.'})}>{current.archived?<RotateCcw size={17}/>:<Archive size={17}/>}<span>{current.archived?'Восстановить':'В архив'}</span></button><button className="btn primary" data-write="" onClick={()=>sm({kind:'edit'})}><Pencil size={16}/> Редактировать</button></div></div>
 <section className="vehicle-hero"><div className="hero-image"><button className="hero-photo-open" aria-label="Открыть фотографии автомобиля" disabled={!current.files.some(f=>f.category==='Фото')} onClick={()=>sp(current.files.find(f=>f.category==='Фото'))}><CarArt car={current} large/></button><div className="hero-badge"><Badge status={current.status}/></div><button className="photo-add" data-write="" onClick={()=>{st('photos');sm({kind:'media',category:'Фото'})}}><ImageIcon size={16}/> Добавить фото</button></div><div className="hero-info"><div className="vin-row"><span>VIN АВТОМОБИЛЯ</span><button disabled={!current.vin} title="Копировать VIN" onClick={()=>{navigator.clipboard.writeText(current.vin).then(()=>tt('VIN скопирован')).catch(()=>tt(current.vin))}}><b>{current.vin||'Не указан'}</b><Copy size={14}/></button></div><div className="hero-info-grid"><div><span><MapPin size={15}/> Местонахождение</span><b>{current.location||'Не указано'}</b></div><div><span><Clock size={15}/> Дней на складе</span><b>{daysInStock(current)===null?'Даты не указаны':daysInStock(current)+(current.soldDate?' · до продажи':' дней')}</b></div><div><span>Покупка</span><b>{date(current.purchaseDate)}</b></div><div><span>Пробег</span><b>{current.mileage===null||current.mileage===undefined?'Не указан':fmt(current.mileage)+' км'}</b></div></div><div className="hero-finance"><div><span>Себестоимость</span><b>{<CostValue car={current}/>}</b></div><div><span>Цена продажи</span><b className="accent-text">{current.price?money(current.price):'Не задана'}</b></div></div></div></section>
 <div className="tabs">{[['overview','Обзор',LayoutGrid],['photos','Фото',ImageIcon],['files','Документы',Files],['costs','Себестоимость',Wallet],['route','Маршрут',Route],['history','История',History],['avito','Авито',ExternalLink],['telegram','Telegram',ExternalLink],...(isOwner?[['publication','Бум Авто',ExternalLink]]:[])].map(([id,label,I])=><button key={id} className={tab===id?'active':''} onClick={()=>st(id)}><I size={16}/>{label}{['files','photos'].includes(id)&&<em>{current.files.filter(f=>id==='photos'?f.category==='Фото':!['Фото','Видео'].includes(f.category)).length}</em>}</button>)}</div>
 {tab==='avito'&&<Avito key={current.id+':'+current.revision} car={current} cars={cars} api={api} onSaved={upsert} readOnly={readOnly} isOwner={isOwner}/>}
 {tab==='telegram'&&<Telegram key={current.id+':'+current.revision} car={current} api={api} onSaved={upsert} readOnly={readOnly} isOwner={isOwner}/>}
 {tab==='publication'&&isOwner&&<Publication key={current.id+':'+current.revision} car={current} api={api} onSaved={upsert}/>}
 {tab==='overview'&&<div className="overview-grid"><section className="panel"><div className="panel-title"><h2>Данные автомобиля</h2><CarFront size={18}/></div><div className="details-grid">{[['Марка и модель',current.brand+' '+current.model],['Выпуск',current.productionMonth||current.year||'—'],['Собственник',current.owner||'Не указан'],['Страна вывоза',current.country||'—'],['Таможня',current.customsCountry||'—'],['Цвет',current.color||'—'],['Дата поступления',date(current.stockDate)],['Дата продажи',date(current.soldDate)],['Контакт',current.contact||'Не указан'],['Покупатель',current.buyer?.fullName||'Не добавлен'],['Продавец',current.seller?.fullName||'Не добавлен'],['Статус документов',current.documentStatus||'Нет'],['Документов и фото',current.files.length]].map(([k,v])=><div key={k}><span>{k}</span><b>{v}</b></div>)}</div><div className="notes"><span>Заметки</span><p>{current.notes||'Пока нет заметок. Добавьте их при редактировании карточки.'}</p></div></section><div className="overview-side"><section className="panel"><div className="panel-title"><h2>Экономика автомобиля</h2><Wallet size={18}/></div><div className="finance-line"><span>Себестоимость</span><b>{<CostValue car={current}/>}</b></div><div className="finance-line"><span>Цена продажи</span><b>{current.price?money(current.price):'—'}</b></div><div className="finance-line total"><span>Плановая разница</span><b className={current.price&&current.price-costTotal(current)<0?'red-text':'green-text'}>{current.price&&costTotal(current)!==null?money(current.price-costTotal(current)):'—'}</b></div><p className="fine-print">Цена продажи минус учтённые расходы. Не является чистой прибылью.</p><button className="text-btn" onClick={()=>st('costs')}>Открыть состав расходов <ArrowUpRight size={15}/></button></section><section className="panel"><div className="panel-title"><h2>Последнее изменение</h2><History size={18}/></div><span className="fine-print">{stamp(current.history[0].date)}</span><h3>{current.history[0].title}</h3><p className="muted-text line-clamp">{current.history[0].detail}</p><button className="text-btn" onClick={()=>st('history')}>Вся история <ArrowUpRight size={15}/></button></section></div></div>}
 {tab==='files'&&<DocumentStatus readOnly={readOnly} key={current.id+':'+current.revision} car={current} onSave={async value=>{const c=await api('/cars/'+current.id+'/document-status',{method:'PATCH',body:{revision:current.revision,value}});upsert(c);tt('Статус документов сохранён')}}/>}
 {tab==='files'&&<section className="panel parties-panel"><div className="panel-title"><div><h2>Покупатель и продавец</h2><p>Данные сторон для документов этого автомобиля</p></div></div><div className="parties-grid">{['buyer','seller'].map(role=><PartyCard readOnly={readOnly} key={role} role={role} party={current[role]} car={current} onUpload={files=>uploadPassport(role,files)} onDelete={deleteDocument} onRecognized={recognized=>sm({kind:'party',role,recognized})} onEdit={()=>sm({kind:'party',role})}/>)}</div><div className="contract-setup"><div><b>Договор купли-продажи</b><p>{current.buyer&&current.seller?'Шаблон подключён. Укажите стоимость, инвойс и дату — стороны и автомобиль подставятся автоматически.':'Сначала добавьте продавца и покупателя.'}</p></div><button className="btn primary" disabled={!current.buyer||!current.seller} title={!current.buyer||!current.seller?'Добавьте обе стороны':'Создать редактируемый Word-файл'} data-write="" onClick={()=>sm({kind:'contract'})}><FileText size={17}/> Сгенерировать договор</button></div>{current.files.filter(f=>f.contract).length>0&&<div className="generated-contracts"><h3>Сформированные договоры</h3>{current.files.filter(f=>f.contract).map(f=><div className="passport-saved-file" key={f.id}><DocumentLink car={current} file={f}/>{!readOnly&&<IconBtn label={'Удалить '+f.name} onClick={()=>deleteDocument(f)}><Trash2 size={16}/></IconBtn>}</div>)}</div>}</section>}
 {tab==='files'&&<VehicleDocuments car={current} api={api} onUpdate={upsert} onDelete={deleteDocument} readOnly={readOnly}/>}
 {tab==='files'&&<PaymentSection key={current.id} car={current} api={api} onUpdate={upsert} onDelete={deleteDocument} readOnly={readOnly}/>}
 {['photos','files'].includes(tab)&&<CarFiles onMove={async (f,direction)=>{try{upsert(await api('/cars/'+current.id+'/photo-order',{method:'PATCH',body:{revision:current.revision,fileId:f.id,direction}}))}catch(e){tt(e.message)}}} onCover={async f=>{try{upsert(await api('/cars/'+current.id+'/cover',{method:'PATCH',body:{revision:current.revision,fileId:f.id}}));tt('Обложка обновлена')}catch(e){tt(e.message)}}} onGenerate={()=>sm({kind:'generate-photo'})} car={current} photos={tab==='photos'} onVideo={()=>sm({kind:'media',category:'Видео'})} onUpload={()=>sm({kind:tab==='photos'?'media':'upload',category:tab==='photos'?'Фото':'Документ'})} onPreview={sp} onDelete={f=>sm({kind:'confirm',action:'files',item:f,title:'Удалить файл?',text:f.name+' будет удалён из облака. Это действие нельзя отменить.'})}/>}
 {tab==='photos'&&<CarVideos car={current} onUpload={()=>sm({kind:'media',category:'Видео'})} onDelete={f=>sm({kind:'confirm',action:'files',item:f,title:'Удалить видео?',text:f.name+' будет удалено из облака.'})}/>}
 {tab==='costs'&&<section className="panel"><div className="panel-title"><div><h2>Состав себестоимости</h2><p>Стоимость и расходы по вашим курсам</p></div><button className="btn primary" data-write="" onClick={()=>sm({kind:'cost'})}><Plus size={17}/> Добавить расход</button></div><CostBasis readOnly={readOnly} key={current.id+':'+current.revision} car={current} onSave={async values=>{const c=await api('/cars/'+current.id+'/cost-basis',{method:'PATCH',body:{revision:current.revision,values}});upsert(c);tt('Себестоимость сохранена')}}/><div className="cost-total"><div><span>ИТОГО СЕБЕСТОИМОСТЬ</span><strong>{<CostValue car={current}/>}</strong></div><span>Включая неоплаченные расходы</span></div><PaymentSummary car={current}/>{current.costs.length?<div className="table-wrap"><table className="cost-table"><thead><tr><th>Статья / описание</th><th>Дата</th><th>Сумма / курс</th><th>В рублях</th><th>Оплата</th><th/></tr></thead><tbody>{current.costs.map(x=><tr key={x.id}><td><b>{x.type}</b><small>{x.description||'—'}</small></td><td>{date(x.date)}</td><td>{fmt(x.amount)} {x.currency}<small>{x.rate==null?'Общий курс':'Курс'}: {expenseRate(current,x)||'не указан'}</small></td><td><b>{expenseRate(current,x)?money(Math.round(x.amount*100*expenseRate(current,x))/100):'Нужен курс'}</b></td><td><PaidToggle paid={x.paid===true} label={x.type} disabled={readOnly} onChange={async paid=>{const c=await api('/cars/'+current.id+'/costs/'+x.id,{method:'PATCH',body:{revision:current.revision,paid}});upsert(c);tt('Статус оплаты сохранён')}}/></td><td><div className="row-actions"><IconBtn label={'Изменить '+x.type} data-write="" onClick={()=>sm({kind:'cost',item:x})}><Pencil size={15}/></IconBtn><IconBtn label={'Удалить '+x.type} data-write="" onClick={()=>sm({kind:'confirm',action:'costs',item:x,title:'Удалить расход?',text:x.type+' · '+money(x.amount*expenseRate(current,x))+'. Себестоимость пересчитается; запись об удалении останется в истории.'})}><Trash2 size={15}/></IconBtn></div></td></tr>)}</tbody></table></div>:<div className="empty"><Wallet size={30}/><h3>Дополнительных расходов пока нет</h3><p>Основные расходы заполняются выше. Здесь можно добавить другие затраты.</p></div>}</section>}
 {tab==='route'&&<section className="panel"><div className="panel-title"><h2>Маршрут автомобиля</h2><button className="btn primary" data-write="" onClick={()=>sm({kind:'route'})}><Plus size={17}/> Добавить</button></div><div className="route-stages">{stageTimeline(current.route).map(r=><div className={'route-stage '+(r.current?'current':'')} key={r.id}><div className="route-stage-heading"><b>{r.label}</b><div className="route-stage-actions"><time>{date(r.date)}</time>{!readOnly&&<IconBtn label="Изменить этап" onClick={()=>sm({kind:'route',item:r})}><Pencil size={17}/></IconBtn>}</div></div><span>{r.finished?'Маршрут завершён':r.current?'На текущем этапе: '+r.days+' дн.':'До следующего этапа: '+r.days+' дн.'}</span></div>)}</div>{!stageTimeline(current.route).length&&<p className="muted-text">Добавьте первый этап и его дату.</p>}<RouteSummary route={current.route}/>{current.route.some(r=>!r.stage)&&<details className="route-previous"><summary>Ранее записанные изменения</summary>{[...current.route].filter(r=>!r.stage).sort((a,b)=>a.date.localeCompare(b.date)).map(r=><div className="route-stage" key={r.id}><div className="route-stage-heading"><b>{r.status} · {r.location||'Место не указано'}</b><time>{date(r.date)}</time></div>{r.note&&<span>{r.note}</span>}</div>)}</details>}</section>}
 {tab==='history'&&<section className="panel"><div className="panel-title"><div><h2>История изменений</h2><p>Автоматическая хронология действий · новые события сверху</p></div><span className="subtle-pill">{current.history.length} событий</span></div><div className="timeline">{current.history.map(h=><div className="timeline-item" key={h.id}><span className="timeline-dot"><History size={13}/></span><div><time>{stamp(h.date)}</time><h3>{h.title}</h3><small className="event-author">{h.actor?.name||'До введения учётных записей'}</small><p className="preserve">{h.detail}</p></div></div>)}</div></section>}
 </>:nav==='encar'?<Encar api={api} readOnly={readOnly}/>:nav==='staff'?null:<><div className="page-heading"><div><div className="eyebrow">VECTOR / {nav==='cars'?'INVENTORY':nav==='files'?'DOCUMENTS':'ACTIVITY'}</div><h1>{nav==='cars'?'Автомобили':nav==='files'?'Документы':nav==='intake'?'Из групп Telegram':nav==='staff'?'Доступы':nav==='encar'?'Расчёт Encar':'История изменений'}{nav==='cars'&&<span className="heading-count">{active.length}</span>}</h1><p>{nav==='cars'?'Каждый автомобиль под контролем. От покупки до продажи.':nav==='files'?'Инвойсы, договоры и чеки по всем автомобилям.':'Все действия в вашем автомобильном бизнесе.'}</p></div><div className="heading-actions">{nav==='cars'&&<>{!readOnly&&<CarImport api={api} onDone={refresh}/>}<button className="btn export-btn" onClick={exportData}><Download size={17}/> Экспорт</button><button className="btn primary" data-write="" onClick={()=>sm({kind:'new'})}><Plus size={19}/> Добавить автомобиль</button></>}</div></div>
 {nav==='cars'&&<><div className="stats-grid">{[[CarFront,'Автомобилей в работе',active.filter(c=>c.status!=='Продан').length,'Весь активный склад',''],[PackageCheck,'Прибыли',active.filter(c=>['Прибыл','На складе'].includes(c.status)).length,'Автомобили доставлены','green'],[Truck,'В процессе доставки',active.filter(c=>['В пути в Бишкек','В пути в Воронеж','В пути','На таможне'].includes(c.status)).length,'В Бишкек или Воронеж','blue'],[Wallet,'Вложено в автомобили',money(inventoryTotal),'По учтённым расходам','orange']].map(([I,label,value,sub,color])=><div className={'stat '+color} key={label}><div><span>{label}</span><I size={19}/></div><strong>{value}</strong><small><span className="tiny-dot"/>{sub}</small></div>)}</div>
 <section className="inventory-panel"><div className="inventory-top"><div className="inventory-title"><h2>{archive?'Архив автомобилей':'Ваш автопарк'}</h2><span>{filtered.length} авто</span></div><div className="view-switch"><IconBtn label="Список" onClick={()=>sv('list')} className={'icon-btn '+(view==='list'?'selected':'')}><List size={18}/></IconBtn><IconBtn label="Карточки" onClick={()=>sv('grid')} className={'icon-btn '+(view==='grid'?'selected':'')}><LayoutGrid size={17}/></IconBtn></div></div><div className="toolbar"><div className="search-field"><Search size={18}/><input placeholder="Поиск по марке, VIN, клиенту…" aria-label="Поиск автомобилей" value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<IconBtn label="Очистить поиск" onClick={()=>setQuery('')}><X size={14}/></IconBtn>}</div><select aria-label="Страна вывоза" title="Фильтр по стране вывоза" value={country} onChange={e=>sc(e.target.value)}><option value="Все страны">Все страны вывоза</option>{[...EXPORT_ORIGINS,...[...new Set(cars.map(c=>c.country).filter(x=>x&&!EXPORT_ORIGINS.includes(x)))].sort()].map(x=><option key={x}>{x}</option>)}<option>Не указана</option></select><select aria-label="Сортировка" value={sort} onChange={e=>so(e.target.value)}><option value="new">Сначала новые</option><option value="country">По стране вывоза</option><option value="name">По названию</option><option value="cost">По себестоимости ↓</option><option value="days">По дням на складе ↓</option></select><button className={'btn archive-filter '+(archive?'chosen':'')} onClick={()=>sa(!archive)}><Archive size={16}/>{archive?'Выйти из архива':'Архив'}</button></div><div className="status-filters">{['Все',...STATUSES].map(s=><button key={s} className={status===s?'active':''} onClick={()=>ss(s)}>{s}{s==='Все'&&<span>{cars.filter(c=>c.archived===archive).length}</span>}</button>)}</div>
 {!filtered.length?<div className="empty"><Search size={30}/><h3>{cars.length?'Автомобили не найдены':'Добавьте первый автомобиль'}</h3><p>{cars.length?'Попробуйте другой запрос или сбросьте фильтры.':'Начните с марки и модели — карточку можно дополнить позже.'}</p><button className="btn" onClick={()=>{if(!cars.length)sm({kind:'new'});else{ss('Все');sc('Все страны');setQuery('');sa(false)}}}>{cars.length?'Сбросить фильтры':'Добавить автомобиль'}</button></div>:view==='list'?<div className="table-wrap"><table className="inventory-table"><thead><tr><th>Автомобиль <ArrowDown size={12}/></th><th>Статус</th><th>Местонахождение</th><th>Себестоимость</th><th>Цена продажи</th><th>На складе</th><th>На сайт</th><th/></tr></thead><tbody>{filtered.map(c=><tr key={c.id} onClick={()=>open(c)}><td><div className="vehicle-cell"><div className="thumb"><CarArt car={c}/></div><div><button className="vehicle-title" onClick={e=>{e.stopPropagation();open(c)}}>{c.brand} <b>{c.model}</b></button><p>{c.year||'Год не указан'} <i>·</i> {c.color||'Цвет не указан'}{c.isDemo&&<span className="demo-label">ДЕМО</span>}</p><span className="vin-small">{c.vin}</span><small className="inventory-mileage">{c.mileage==null?'Пробег не указан':fmt(c.mileage)+' км'}</small></div></div></td><td><Badge status={c.status}/></td><td><span className="location-cell"><MapPin size={14}/>{c.location||'—'}</span><small>{c.country||'Страна вывоза не указана'}</small></td><td><strong className="inventory-money">{money(costTotal(c))}</strong></td><td><SalePrice car={c} onSaved={upsert} readOnly={readOnly}/></td><td><span className={'days '+((daysInStock(c)||0)>30?'long':'')}>{daysInStock(c)===null?'—':daysInStock(c)+' дн.'}</span></td><td><WebsiteToggle car={c} api={api} onSaved={upsert} canEdit={isOwner}/></td><td><div className="row-actions">{isOwner&&<IconBtn label="Удалить автомобиль" onClick={e=>{e.stopPropagation();deleteCar(c)}}><Trash2 size={17}/></IconBtn>}<ChevronRight size={18} className="row-chevron"/></div></td></tr>)}</tbody></table></div>:<div className="car-grid">{filtered.map(c=><article className="vehicle-tile" key={c.id} onClick={()=>open(c)}><WebsiteToggle car={c} api={api} onSaved={upsert} canEdit={isOwner}/><div className="tile-image"><CarArt car={c}/><Badge status={c.status}/></div><div className="tile-info"><span>{c.year||'Год не указан'} · {c.color}{c.isDemo?' · ДЕМО':''}</span><h3>{c.brand} {c.model}</h3><small className="inventory-mileage">{c.mileage==null?'Пробег не указан':fmt(c.mileage)+' км'}</small><p><MapPin size={14}/>{c.location||'Не указано'}</p><div><b>{<CostValue car={c}/>}</b>{isOwner&&<IconBtn label="Удалить автомобиль" onClick={e=>{e.stopPropagation();deleteCar(c)}}><Trash2 size={17}/></IconBtn>}<ArrowUpRight size={17}/></div></div></article>)}</div>}<div className="table-footer"><span>Показано {filtered.length} из {cars.filter(c=>c.archived===archive).length} автомобилей</span><span><Cloud size={14}/> Данные сохраняются в облаке</span></div></section>
 {demoCount>0&&<div className="demo-banner"><div><span className="demo-icon"><CarFront size={20}/></span><div><b>Ваш склад готов к работе</b><p>Здесь {demoCount} тестовых автомобилей. Добавьте свой — или изучите любую карточку.</p></div></div><button data-owner="" data-write="" onClick={()=>sm({kind:'confirm',action:'demo',title:'Удалить тестовые автомобили?',text:`Будут удалены ${demoCount} тестовых карточек и прикреплённые к ним файлы, включая ваши изменения в этих карточках. Ваши собственные автомобили останутся.`})}>Убрать демоданные <X size={15}/></button></div>}</>}
 {nav==='files'&&<section className="panel"><div className="toolbar"><div className="search-field"><Search size={18}/><input placeholder="Найти файл или автомобиль…" aria-label="Поиск документов" value={query} onChange={e=>setQuery(e.target.value)}/></div><select aria-label="Тип документа" value={fileFilter} onChange={e=>sff(e.target.value)}>{['Все',...FILE_TYPES.filter(x=>!['Фото','Видео'].includes(x))].map(x=><option key={x}>{x}</option>)}</select></div>{!allFiles.length?<div className="empty"><Files size={34}/><h3>Здесь будут ваши документы</h3><p>Откройте вкладку «Документы» в карточке автомобиля и загрузите договор, инвойс или чек.</p><button className="btn" onClick={()=>go('cars')}>К автомобилям <ArrowUpRight size={15}/></button></div>:<div className="file-list">{allFiles.map(f=><div className="file-row" key={f.id}><span className="file-icon"><FileText/></span><div className="file-name"><DocumentLink car={f.car} file={f}/><button className="text-btn" onClick={()=>open(f.car)}>{f.car.brand} {f.car.model} · {f.car.vin}</button><span>{f.category} · {size(f.size)} · {date(f.date)}</span></div></div>)}</div>}</section>}
 {nav==='history'&&<section className="panel"><div className="panel-title"><h2>Лента событий</h2><span className="subtle-pill">{allHistory.length} событий</span></div>{!allHistory.length?<div className="empty"><History/><h3>Пока нет событий</h3></div>:<div className="timeline">{allHistory.map(h=><div className="timeline-item" key={h.id}><span className="timeline-dot"><History size={14}/></span><div><time>{stamp(h.date)}</time><h3>{h.title}</h3><small className="event-author">{h.actor?.name||'До введения учётных записей'}</small><button className="text-btn" onClick={()=>open(h.car)}>{h.car.brand} {h.car.model} <ArrowUpRight size={13}/></button><p className="preserve">{h.detail}</p></div></div>)}</div>}</section>}
 </>}
 <footer className="footer"><span>VECTOR CRM <i>·</i> Ваш бизнес. В полном порядке.</span><button onClick={()=>sm({kind:'help'})}><HelpCircle size={14}/> Как пользоваться</button></footer></div></main>
 {modal?.kind==='generate-photo'&&current&&<Modal title="Сгенерировать фото" onClose={()=>!busy&&sm(null)} wide><GeneratePhoto car={current} api={api} onBusy={sb} onSaved={c=>{upsert(c);sm(null);tt('Фото сохранено в карточке')}}/></Modal>}
 {modal?.kind==='media' &&current&&<Modal title={modal.category==='Фото'?'Добавить фотографии':'Добавить видео'} subtitle={current.brand+' '+current.model} onClose={()=>!busy&&sm(null)}><MediaUpload onBusy={sb} car={current} category={modal.category} upload={async(item,category,revision)=>{const fd=new FormData();fd.set('file',item.file);fd.set('category',category);fd.set('revision',revision);fd.set('uploadId',item.id);const c=await api('/cars/'+current.id+'/files',{method:'POST',body:fd});upsert(c);return c}} onDone={n=>{sm(null);tt('Загружено файлов: '+n)}}/></Modal>}
 {['new','edit'].includes(modal?.kind)&&<CarForm cars={cars} car={modal.kind==='edit'?current:null} onSave={saveCar} onClose={()=>sm(null)}/>}{['cost','route','upload'].includes(modal?.kind)&&current&&<SmallForm kind={modal.kind} car={current} item={modal.item} category={modal.category} onSave={saveSmall} onClose={()=>sm(null)}/>}
 {modal?.kind==='party'&&current&&<PartyForm role={modal.role} party={current[modal.role]} recognized={modal.recognized} onSave={saveParty} onClose={()=>sm(null)}/>}
 {modal?.kind==='contract'&&current&&<ContractForm car={current} onSave={saveContract} onClose={()=>sm(null)}/>}
 {modal?.kind==='confirm'&&<Modal title={modal.title} onClose={()=>!busy&&sm(null)}><div className="modal-body"><p className="confirm-text">{modal.text}</p></div><div className="modal-foot"><button className="btn" disabled={busy} data-write="" onClick={()=>sm(null)}>Отмена</button><button className={'btn '+(modal.action==='archive'?'primary':'danger')} disabled={busy} onClick={confirmed}>{busy?<Loader2 className="spin" size={16}/>:<Check size={16}/>} {modal.action==='archive'?'Подтвердить':'Удалить'}</button></div></Modal>}
 {modal?.kind==='help'&&<Modal title="VECTOR CRM готова к работе" subtitle="Управляйте складом через привычные формы." onClose={()=>sm(null)}><div className="modal-body help-body"><div><CarFront/><section><h3>Добавьте автомобиль</h3><p>Нажмите «Добавить автомобиль», укажите VIN, марку и модель. Статус и остальные данные можно изменить в карточке.</p></section></div><div><Wallet/><section><h3>Соберите себестоимость</h3><p>Во вкладке «Себестоимость» добавьте покупку, доставку и другие расходы. Для валютных платежей укажите свой курс.</p></section></div><div><Upload/><section><h3>Сохраните документы</h3><p>Во вкладке «Фото» загружайте фотографии автомобиля. Во вкладке «Документы» — документы и сканы, а кнопками «+» добавляйте покупателя и продавца. До 10 МБ на файл. Первое фото станет обложкой.</p></section></div><div><Route/><section><h3>Отмечайте перемещения</h3><p>Добавляйте этапы маршрута. Дни на складе считаются с даты поступления; после продажи счётчик останавливается.</p></section></div><p className="help-note">Карточки и файлы сохраняются в облаке. Экспорт на экране автомобилей выгружает данные в JSON; сами вложения скачиваются из карточек отдельно. При одновременном изменении в двух вкладках CRM попросит обновить данные.</p></div><div className="modal-foot"><button className="btn primary" data-write="" onClick={()=>sm(null)}>Всё понятно <Check size={16}/></button></div></Modal>}
 {photo&&current&&<PhotoViewer car={current} initial={photo} onClose={()=>sp(null)}/>}
 {toast&&<div className="toast" role="status"><CheckCircle2 size={18}/><span>{toast}</span><IconBtn label="Закрыть уведомление" onClick={()=>tt('')}><X size={15}/></IconBtn></div>}
 </div>
}
createRoot(document.getElementById('root')).render(<AccessGate api={api}>{session=><App key={session.role} session={session}/>}</AccessGate>);
